  "id": 3408916452,
  "name": "Second Tuesday Monologues - Shadows",
  "venue": "The Common Counter",
  "address": "118 Bethnal Green Road,  London,  E2 6DG",
  "time": "19:00-21:00",
  "date": "Sep 9",
  "price": "Free",
